import { motion } from "framer-motion";

import { fadeUp } from "@/lib/motion";
import { useLanguage } from "@/lib/i18n";
import { IMAGE_CREDITS } from "@/data/image-credits";

/**
 * Credits for the photographs behind the cover images.
 *
 * Unsplash's API terms require the photographer to be credited with a link
 * back to their profile. The covers are composited — headline over photograph
 * — so there is nowhere on the image itself to carry that, and it lives here.
 *
 * The list is generated by scripts/build-image-credits.mjs from the fetch
 * manifest, so it cannot fall out of step with what is actually on the site.
 */
export default function ImageCreditsPage() {
  const { t } = useLanguage();

  return (
    <div className="mx-auto max-w-2xl px-4 sm:px-6 py-16 space-y-10">
      <motion.div
        variants={fadeUp}
        initial="hidden"
        animate="visible"
        className="space-y-2"
      >
        <h1 className="text-4xl font-extrabold">
          <span className="gradient-text">{t("credits.title")}</span>
        </h1>
        <p className="text-sm text-muted-foreground">{t("credits.subtitle")}</p>
      </motion.div>

      <p className="text-muted-foreground leading-relaxed">
        {t("credits.intro")}
      </p>

      <ul className="space-y-4">
        {IMAGE_CREDITS.map((credit) => (
          <li
            key={credit.file}
            className="glass-card rounded-xl p-4 flex items-center gap-4"
          >
            <img
              src={credit.file}
              alt=""
              loading="lazy"
              width={128}
              height={67}
              className="w-32 shrink-0 rounded-lg object-cover aspect-video"
            />
            <div className="min-w-0 space-y-1">
              <p className="font-semibold leading-snug">{credit.title}</p>
              <p className="text-sm text-muted-foreground">
                {t("credits.photo_by")}{" "}
                <a
                  href={credit.photographerUrl}
                  target="_blank"
                  rel="noopener noreferrer nofollow"
                  className="text-primary hover:underline"
                >
                  {credit.photographer}
                </a>{" "}
                <a
                  href={credit.source}
                  target="_blank"
                  rel="noopener noreferrer nofollow"
                  className="hover:underline"
                >
                  ({t("credits.on_unsplash")})
                </a>
              </p>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}
